# BitLocker requires Windows Pro/Enterprise/Education (absent on Home).
if (Get-Command Enable-BitLocker -ErrorAction SilentlyContinue) {
    Enable-BitLocker -MountPoint 'G:' -EncryptionMethod XtsAes256 -UsedSpaceOnly -RecoveryPasswordProtector -SkipHardwareTest
    if ('G:' -eq $env:SystemDrive) { Add-BitLockerKeyProtector -MountPoint 'G:' -TpmProtector } else { Enable-BitLockerAutoUnlock -MountPoint 'G:' }
} else {
    Write-Warning 'BitLocker is unavailable on this Windows edition.'
}
